#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, l; long long d;
    cin >> n >> d >> l;
    int P = (n + 1) / 2, N = n / 2;                  // odd positions are +, even are -
    long long mx = (long long)P * l - N, mn = P - (long long)N * l;
    if (d > mx || d < mn) { cout << -1 << "\n"; return 0; }
    long long R = mx - d;                            // how much to pull down from the max setup
    vector<long long> v(n);
    for (int i = 0; i < n; i++) v[i] = (i % 2 == 0) ? l : 1;
    for (int i = 0; i < n && R > 0; i++) {
        long long step = min<long long>(R, l - 1);
        if (i % 2 == 0) v[i] -= step; else v[i] += step;
        R -= step;
    }
    for (int i = 0; i < n; i++) cout << v[i] << (i + 1 < n ? ' ' : '\n');
}

