int main(){
    long long n, k; cin >> n >> k;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    if (k == 1) { cout << n << "\n"; return 0; }
    set<long long> S(a.begin(), a.end());
    sort(a.begin(), a.end());
    long long ans = 0;
    for (long long x : a) {
        if (x % k == 0 && S.count(x / k)) continue;   // not the start of a chain x, xk, xk^2, ...
        long long len = 0, c = x;
        while (S.count(c)) { len++; c *= k; }
        ans += (len + 1) / 2;                          // alternate picks along a chain
    }
    cout << ans << "\n";
}

