int main(){
    long long n, m, s, f;
    cin >> n >> m >> s >> f;
    vector<array<long long,3>> w(m);
    for (auto &x : w) cin >> x[0] >> x[1] >> x[2];       // time, l, r
    string out;
    long long p = s, t = 1;
    int idx = 0;
    while (p != f) {
        long long d = (f > p) ? 1 : -1;
        bool blocked = false;
        if (idx < m && w[idx][0] == t) {
            long long l = w[idx][1], r = w[idx][2];
            auto in = [&](long long q) { return q >= l && q <= r; };
            blocked = in(p) || in(p + d);
        }
        if (blocked) out += 'X';                         // wait while the next spy is watched
        else { out += (d == 1 ? 'R' : 'L'); p += d; }    // otherwise move toward f at once
        if (idx < m && w[idx][0] == t) idx++;
        t++;
    }
    cout << out << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n, l, r, Ql, Qr;
    cin >> n >> l >> r >> Ql >> Qr;
    vector<long long> w(n), pre(n + 1, 0);
    for (int i = 0; i < n; i++) { cin >> w[i]; pre[i+1] = pre[i] + w[i]; }
    long long best = LLONG_MAX;
    for (long long L = 0; L <= n; L++) {               // left arm takes items 1..L, right arm the rest
        long long R = n - L;
        long long cost = pre[L] * l + (pre[n] - pre[L]) * r;
        if (L > R) cost += Ql * (L - R - 1);           // best interleaving: runs alternate
        else if (R > L) cost += Qr * (R - L - 1);
        best = min(best, cost);
    }
    cout << best << "\n";
}

