int main(){
    int T; cin >> T;
    while (T--) {
        vector<string> g(8);
        for (auto &r : g) cin >> r;
        vector<int> ks;
        for (int i = 0; i < 64; i++) if (g[i/8][i%8] == 'K') ks.push_back(i);
        auto nb = [&](int p) {
            vector<int> v;
            for (int dr : {2, -2}) for (int dc : {2, -2}) {
                int r = p / 8 + dr, c = p % 8 + dc;
                if (r >= 0 && r < 8 && c >= 0 && c < 8) v.push_back(r * 8 + c);
            }
            return v;
        };
        vector<char> vis(64 * 64, 0);
        queue<int> q;
        int s = ks[0] * 64 + ks[1];
        vis[s] = 1; q.push(s);
        bool ok = false;
        while (!q.empty() && !ok) {
            int st = q.front(); q.pop();
            for (int x : nb(st / 64)) for (int y : nb(st % 64)) {
                int ns = x * 64 + y;
                if (vis[ns]) continue;
                vis[ns] = 1;
                if (x == y && g[x/8][x%8] != '#') ok = true;
                q.push(ns);
            }
        }
        cout << (ok ? "YES" : "NO") << "\n";
    }
}

