    string s; cin >> s;
    long long ans = 1, run = 0;                       // run = length of current chain of adjacent pairs summing to 9
    auto flush = [&]() {
        if (run > 0 && run % 2 == 0) ans *= (run / 2 + 1);   // even chain of L edges has L/2+1 maximum matchings
        run = 0;
    };
    for (size_t i = 0; i + 1 < s.size(); i++) {
        if ((s[i] - '0') + (s[i+1] - '0') == 9) run++;
        else flush();
    }
    flush();
    cout << ans << "\n";
}

