using namespace std;
int main(){
    int n, m, k;
    cin >> n >> m >> k;
    for (int i = 0; i < n * m; i++) { int x; cin >> x; }   // values are irrelevant: the pair list only depends on m
    // Batcher odd-even merge sort on the next power of two, keeping only comparators inside [0, m)
    int N = 1; while (N < m) N *= 2;
    vector<pair<int,int>> ops;
    for (int p = 1; p < N; p += p)
        for (int kk = p; kk > 0; kk /= 2)
            for (int j = kk % p; j + kk < N; j += kk + kk)
                for (int i = 0; i < kk; i++)
                    if (j + i + kk < N && (j + i) / (p + p) == (j + i + kk) / (p + p)) {
                        int lo = j + i, hi = j + i + kk;
                        if (hi < m) ops.push_back({lo, hi});
                    }
    cout << ops.size() << "\n";
    for (auto [lo, hi] : ops) {
        if (k == 0) cout << lo + 1 << ' ' << hi + 1 << "\n";   // swap when a[lo] > a[hi]: min goes to lo
        else        cout << hi + 1 << ' ' << lo + 1 << "\n";   // swap when a[hi] > a[lo]: max goes to lo
    }
}

