#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, x;
    cin >> n >> x;
    vector<array<int,3>> c(n);                       // type, height, mass
    for (auto &e : c) cin >> e[0] >> e[1] >> e[2];
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return c[a][1] < c[b][1]; });
    int best = 0;
    for (int start = 0; start < 2; start++) {
        priority_queue<pair<int,int>> pq[2];          // max-heap of eligible candies per type, keyed by mass
        int cur = x, idx = 0, eaten = 0, t = start;
        while (true) {
            while (idx < n && c[order[idx]][1] <= cur) { int e = order[idx++]; pq[c[e][0]].push({c[e][2], e}); }
            if (pq[t].empty()) break;
            cur += pq[t].top().first; pq[t].pop();   // eat the heaviest eligible candy of the required type
            eaten++; t ^= 1;
        }
        best = max(best, eaten);
    }
    cout << best << "\n";
}

