int main(){
    string s; cin >> s;
    int n = s.size(), opens = 0, closes = 0, hashes = 0, last = -1;
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') opens++;
        else if (s[i] == ')') closes++;
        else { hashes++; last = i; }
    }
    int rest = opens - closes - (hashes - 1);        // the last '#' absorbs the surplus
    if (rest < 1) { cout << -1 << "\n"; return 0; }
    int bal = 0;
    string out;
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') bal++;
        else if (s[i] == ')') bal--;
        else {
            int v = (i == last) ? rest : 1;
            bal -= v;
            out += to_string(v) + "\n";
        }
        if (bal < 0) { cout << -1 << "\n"; return 0; }
    }
    cout << out;
}

