    int n; cin >> n;
    vector<int> deg(n), s(n);
    for (int i = 0; i < n; i++) cin >> deg[i] >> s[i];
    queue<int> q;
    for (int i = 0; i < n; i++) if (deg[i] == 1) q.push(i);
    vector<pair<int,int>> edges;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (deg[v] != 1) continue;
        int u = s[v];                                  // the only remaining neighbour of leaf v
        edges.push_back({v, u});
        deg[v] = 0;
        deg[u]--;
        s[u] ^= v;                                     // remove v from u's neighbour XOR
        if (deg[u] == 1) q.push(u);
    }
    cout << edges.size() << "\n";
    for (auto [a, b] : edges) cout << a << ' ' << b << "\n";
}

