int main(){
    int n; string s, t;
    cin >> n >> s >> t;
    vector<int> first(676, -1);                        // first mismatch position of each (s_i, t_i) type
    int d = 0;
    for (int i = 0; i < n; i++) if (s[i] != t[i]) {
        d++;
        int key = (s[i] - 'a') * 26 + (t[i] - 'a');
        if (first[key] < 0) first[key] = i;
    }
    int best = d, p = -1, q = -1;
    for (int k1 = 0; k1 < 676; k1++) {
        if (first[k1] < 0) continue;
        int a = k1 / 26, b = k1 % 26;
        for (int k2 = 0; k2 < 676; k2++) {
            if (first[k2] < 0 || k2 == k1) continue;
            int c = k2 / 26, e = k2 % 26;
            int gain = (c == b) + (a == e);            // mismatches fixed by swapping the two positions
            if (gain > 0 && d - gain < best) { best = d - gain; p = first[k1]; q = first[k2]; }
        }
    }
    cout << best << "\n";
    if (p < 0) cout << "-1 -1\n"; else cout << p + 1 << " " << q + 1 << "\n";
}

