#include <bits/stdc++.h>
using namespace std;
int n, m;
bool rowOk(vector<int> r) {                          // sortable with at most one swap?
    vector<int> bad;
    for (int i = 0; i < m; i++) if (r[i] != i + 1) bad.push_back(i);
    if (bad.empty()) return true;
    if (bad.size() != 2) return false;
    swap(r[bad[0]], r[bad[1]]);
    for (int i = 0; i < m; i++) if (r[i] != i + 1) return false;
    return true;
}
int main(){
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m));
    for (auto &r : a) for (auto &v : r) cin >> v;
    auto check = [&](int j, int k) {                 // column swap j,k (or none if j < 0)
        for (auto r : a) {
            if (j >= 0) swap(r[j], r[k]);
            if (!rowOk(r)) return false;
        }
        return true;
    };
    bool ok = check(-1, -1);
    for (int j = 0; j < m && !ok; j++)
        for (int k = j + 1; k < m && !ok; k++) ok = check(j, k);
    cout << (ok ? "YES" : "NO") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n, k, a, b;
    cin >> n >> k >> a >> b;
    auto rng = [&](long long c) { return make_pair((c + k - 1) / k, c); };   // allowed group counts for c bags
    auto [lo1, hi1] = rng(a);
    auto [lo2, hi2] = rng(b);
    long long x = -1, y = -1;
    for (long long xx = lo1; xx <= hi1 && x < 0; xx++)
        for (long long yy = xx - 1; yy <= xx + 1; yy++)
            if (yy >= 0 && yy >= lo2 && yy <= hi2) { x = xx; y = yy; break; }
    if (x < 0) { cout << "NO\n"; return 0; }
    auto split = [&](long long c, long long g) {     // c bags into g groups, sizes as even as possible
        vector<long long> sz;
        for (long long i = 0; i < g; i++) sz.push_back(c / g + (i < c % g ? 1 : 0));
        return sz;
    };
    auto G = split(a, x), B = split(b, y);
    bool startG = x >= y;
    string res;
    for (long long i = 0; i < x + y; i++) {
        bool isG = ((i % 2 == 0) == startG);
        long long g = i / 2;
        res += string(isG ? G[g] : B[g], isG ? 'G' : 'B');
    }
    cout << res << "\n";
}

