#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// pillows for L beds at distances 1..L from Frodo: x-1, x-2, ... each at least 1
ll side(ll x, ll L) {
    if (L <= 0) return 0;
    if (L <= x - 1) return L * x - L * (L + 1) / 2;
    return (x - 1) * x / 2 + (L - (x - 1));
}
int main(){
    ll n, m, k;
    cin >> n >> m >> k;
    ll lo = 1, hi = m - n + 1, ans = 1;
    while (lo <= hi) {
        ll mid = (lo + hi) / 2;
        ll total = mid + side(mid, k - 1) + side(mid, n - k);
        if (total <= m) { ans = mid; lo = mid + 1; } else hi = mid - 1;
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
