#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<int> fresh;                  // boxes pushed since the last reorder (top = back)
    long long block = 0;                // boxes sitting in the sorted block, smallest on top
    int cur = 1, reorders = 0;
    for (int i = 0; i < 2 * n; i++) {
        string cmd; cin >> cmd;
        if (cmd == "add") { int x; cin >> x; fresh.push_back(x); }
        else {
            if (!fresh.empty() && fresh.back() == cur) fresh.pop_back();
            else {
                if (!fresh.empty()) { reorders++; block += fresh.size(); fresh.clear(); }  // sort the whole stack
                block--;                                                                 // cur is the block's top
            }
            cur++;
        }
    }
    cout << reorders << "\n";
}
